function specDamageMult(id,path=s.spec?.[id]){return ({bolt:{fan:.7,lance:1.2},scatter:{choke:1.25,barrage:.75},frost:{cryo:.75,javelin:1.5},chain:{network:.75,anchor:.55},toxic:{wake:.75,caustic:1.5},gravity:{net:.75,collapse:.75},nova:{wide:.75,echo:.65},laser:{broad:.65,precision:1.2}})[id]?.[path]||newSpecMult(id)}
function specialisationLabel(id,data=s){return specialisations[id]?.find(x=>x.id===(data?.spec||data?.specialisations)?.[id])?.name||''}
function specCardHint(id){let name=specialisationLabel(id);return name?'Path: '+name:specialisations[id]&&s.items[id]?'Level 3: choose a specialisation':''}
function novaBurst(l,mult=1){let radius=(100+l*22)*areaMult()*(s.spec.nova==='wide'?1.4:1);if(s.evolved.nova){let count=0;s.hostile=s.hostile.filter(b=>{if(dist(b,s.p)<radius){count++;reflectShot(b);return false}return true});s.p.shield=Math.min(shieldCapacity()+(s.mutations.overflow?40:0),s.p.shield+10+count*3);radius*=1.15}gasBlast(s.p.x,s.p.y,radius,260);s.fx.push({type:'ring',x:s.p.x,y:s.p.y,r:radius,c:s.evolved.nova?evoStyles.nova.color:'#ffe28c',life:.5,max:.5});for(let t of s.enemies)if(dist(t,s.p)<radius+t.r)hit(t,(24+l*18)*mult,'nova')}
function updateSpecEchoes(dt){let due=[];for(let echo of s.specEchoes){echo.wait-=dt;if(echo.wait<=0)due.push(echo)}s.specEchoes=s.specEchoes.filter(e=>e.wait>0);for(let echo of due){sound('nova');novaBurst(echo.l,echo.mult)}}

let pendingSpec='';
function offerSpecialisation(){if(state!=='play'||!s.spec)return false;let id=Object.keys(specialisations).find(id=>s.items[id]>=3&&!s.spec[id]);if(!id)return false;pendingSpec=id;state='specialise';resetInput();$('specTitle').textContent=defs.find(d=>d.id===id).name+' · Specialise';$('specChoices').innerHTML=specialisations[id].map((x,i)=>'<button class="card" data-spec="'+i+'"><span class="icon">'+equipmentIcon(pendingSpec,!!s.evolved[pendingSpec])+'</span><span class="tag">PATH '+(i+1)+'</span><strong>'+x.name+'</strong><span class="desc">'+x.desc+'</span></button>').join('');show('specialise',true);hud();return true}
function chooseSpecialisation(i){if(state!=='specialise'||!specialisations[pendingSpec]?.[i])return;s.spec[pendingSpec]=specialisations[pendingSpec][i].id;pendingSpec='';show('specialise',false);state='play';hud();levelUp()}
function specDescription(){return Object.entries(s.spec||{}).map(([id,path])=>{let choice=specialisations[id]?.find(x=>x.id===path);return choice?defs.find(d=>d.id===id).name+' · '+choice.name+': '+choice.desc:''}).filter(Boolean).join('<br><br>')||'Raise any of the 32 branching weapons, or Energy Shield, to level 3 to choose a path. See How to play → Weapon specialisations for the list.'}
const weaponRoles={"bolt":{"role":"GENERALIST","tip":"Reliable forward volleys; extra bolts stay focused."},"rapid":{"role":"SUSTAINED FIRE","tip":"Fast pressure on a narrow forward lane."},"cannon":{"role":"EXPLOSIVE BURST","tip":"Slow forward shells punish clustered ships."},"scatter":{"role":"CLOSE BURST","tip":"Best at close range; aim the cone into a group."},"arc":{"role":"RADIAL PIERCING","tip":"One disc aims at a target; the other spokes cover the arena."},"mines":{"role":"PURSUIT TRAP","tip":"Lure following enemies into your planted explosives."},"gravity":{"role":"CROWD CONTROL","tip":"Pull groups into a persistent damaging field."},"singularity":{"role":"HEAVY BLAST","tip":"Rare forward ordnance with large detonations."},"rocket":{"role":"HOMING AREA","tip":"Seeking blasts clear packed groups from many directions."},"seeker":{"role":"TRACKING","tip":"Reliable homing pressure; evolved drones also collect XP."},"nova":{"role":"PERSONAL SPACE","tip":"A periodic radial blast; evolved discharge clears bullets."},"chain":{"role":"PACK CLEAR","tip":"Instant jumps through nearby enemies; fewer returns on a lone target."},"blade":{"role":"CLOSE GUARD","tip":"Strong contact damage around your hull; limited reach."},"toxic":{"role":"AREA DENIAL","tip":"Damage builds while enemies remain inside poison zones."},"frost":{"role":"SLOW & FREEZE","tip":"Radial control gives you space; damage is secondary."},"laser":{"role":"WIDE LANE","tip":"A piercing beam; evolution leaves a damaging corridor."},"harpoon":{"role":"SINGLE-TARGET CONTROL","tip":"Sustained tether damage and slowing pressure."},"ember":{"role":"PURSUIT TRAIL","tip":"Burn the path behind you; overlapping wakes share a hit interval."},"prism":{"role":"ORBITAL COVER","tip":"Satellites aim independently and refract beam combinations."},"scrap":{"role":"PIERCING CONE","tip":"Forward metal spread; explosions can charge its projectiles."},"buoy":{"role":"PLANTED DEFENCE","tip":"Build a defensive position around your lightning pylons."},"saw":{"role":"TRACKING PIERCING","tip":"Homing saws work through multiple ships; evolution adds returns."},"mortar":{"role":"DELAYED SIEGE","tip":"Leads ordinary moving ships; freeze helps hold the blast zone."},"nanite":{"role":"INFECTION","tip":"Damage over time; evolved kills spread infection and heal."},"phaseTorp":{"role":"ARMOUR & RIFTS","tip":"Forward armour-cutting salvo; evolved rift overlap is limited."},"sonic":{"role":"CROWD PUSH","tip":"A close shockwave that knocks pursuing ships away."},"rail":{"role":"LONG ANTI-ARMOUR","tip":"Narrow forward lane; ignores 30% armour, or 60% with Needle."},"flak":{"role":"PROXIMITY BURST","tip":"Shells burst near groups and scatter short-range fragments."},"crescent":{"role":"RETURNING SWEEP","tip":"Piercing crescents hit out and back; evolved volleys stay focused."},"fence":{"role":"LINE TRAP","tip":"Plant a wire and draw enemies across it."},"leech":{"role":"SUSTAIN","tip":"Modest targeted damage with a capped hull repair per hit."},"cryoCharge":{"role":"FREEZE TRAP","tip":"Arm a charge behind you to stop a pursuing group."},"ram":{"role":"FORWARD DEFENCE","tip":"A close pressure wedge clears space in front of your hull."},"sails":{"role":"FLANK GUARD","tip":"Repeated piercing beams protect your sides at range."},"voidSeed":{"role":"DELAYED AREA","tip":"Attached seeds bloom after a delay; best on grouped targets."},"stasisNet":{"role":"CONTROL & INTERCEPT","tip":"Slow a local group and intercept a limited number of shots."}};
Object.assign(weaponRoles,{ionGuard:{role:'ORBITAL GUARD',tip:'Temporary medium-range sentries; cover their downtime with another close defence.'},plasmaRain:{role:'LINGERING POOLS',tip:'Hold enemies in the pools; evolved pools gather towards your ship.'},prismTrace:{role:'REFLECTING PIERCER',tip:'Crystals bounce inside a fixed flight box and can hit again after a reflection.'},cometAxe:{role:'ARCING HEAVY',tip:'Comets curve across the firing lane, striking each ship once.'},ionCurtain:{role:'VERTICAL CORRIDOR',tip:'Clear a path above and below; move sideways to line ships up.'},corona:{role:'CLOSE AURA',tip:'Steady weak contact pressure; evolved kills provide limited hull repair.'},plasmaWhip:{role:'ALTERNATING SWEEP',tip:'Attacks alternate forward and rear relative to your facing.'},twinWisps:{role:'ROTATING BOMBARDMENT',tip:'Circling marked zones reward steering enemies into their paths.'},spire:{role:'DELAYED AREA',tip:'Staggered strikes hit a fixed area; freezing targets keeps them in the storm.'},echoRing:{role:'EXPANDING FRONT',tip:'Each ship is struck once by each travelling ring.'},crossfire:{role:'CROSSING VOLLEY',tip:'Paired side cannons converge on a nearby ship; guidance improves penetration.'},rupture:{role:'HEAVY HULL BREAKER',tip:'Prioritises the toughest nearby hull; a fixed lock-on point limits moving-target damage.'}});
function weaponRole(id){return weaponRoles[id]||{role:"WEAPON",tip:""}}
function weaponBase(id,l){return ({bolt:15+l*7,rapid:6+l*3,cannon:26+l*12,scatter:7+l*4,arc:18+l*9,frost:13+l*7,chain:24+l*14,toxic:4+l*3.5,laser:35+l*22,rocket:28+l*14,seeker:12+l*7,nova:24+l*18,mines:25+l*15,gravity:6+l*4,singularity:65+l*30,blade:12+l*8})[id]||extraBase(id,l)}
function previewDamage(id,l){let d=weaponBase(id,l)*specDamageMult(id),starter=id===s.pilot.starter;if(starter&&['bolt','frost','rapid','cannon'].includes(id))d*=s.pilot.damage;if(id==='rapid')d*=s.spec?.rapid==='volley'?.7:s.spec?.rapid==='rail'?1.5:1;if(id==='cannon'&&s.spec?.cannon==='blast')d*=.9;if(s.evolved[id]){if(id==='corona')d*=1.4;if(id==='plasmaWhip')d*=1.25;if(id==='crossfire')d*=.8;if(id==='harpoon'||id==='sonic')d*=1.3;if(id==='ember')d*=1.4;if(id==='saw')d*=1.25;if(id==='blade')d*=1.6;if(id==='scatter')d*=.85;if(id==='rail')d*=.7;if(id==='crescent'||id==='ram')d*=1.3;if(id==='singularity')d*=1+maxHP()/350}return d*(1+.1*support('power'))*(s.boosts.damage>0?1.75:1)*(s.module==='overdrive'?1.1:1)*(id===s.pilot.starter?(s.tree?.starter||1):1)}
function weaponVolleyCount(id,l){let evolved=!!s.evolved[id],path=s.spec[id];return ({crossfire:(evolved?4:2)*(path==='fan'?2:1),spire:evolved?5:3,echoRing:evolved?2:1,rupture:evolved?2:1,ionGuard:2+Math.floor(l/2),plasmaRain:2,prismTrace:evolved?3:2,cometAxe:evolved?6:3,twinWisps:(evolved?3:2)+(support('spire')?1:0),bolt:1+Math.floor(l/2)+(path==='fan'?2:0),rapid:path==='rail'?1:1+2*Math.floor(l/3)+(path==='volley'?2:0),cannon:1,scatter:4+l+(s.pilot.starter==='scatter'?(s.pilot.pellets||0):0)+(path==='barrage'?3:0),arc:3+Math.floor(l/2),frost:path==='javelin'?3:5+Math.floor(l/2),rocket:3+Math.floor(l/3),seeker:2+Math.floor(l/2),prism:(evolved?4:2+Math.floor(l/3))*(evolved?2:1),scrap:5+l,saw:2+Math.floor(l/3),nanite:2+Math.floor(l/2),phaseTorp:evolved?3:2,crescent:(evolved?3:2)+(path==='wide'?1:0),rail:(evolved?2:1)*(path==='fan'?3:1),leech:evolved?2:1,sails:evolved?4:2,chain:path==='anchor'?3:2+l+(path==='network'?2:0),voidSeed:1+Math.floor(l/3),mortar:evolved?3:1})[id]||0}
function volleyUpgradeHint(id,l,n){let before=l?weaponVolleyCount(id,l):0,after=weaponVolleyCount(id,n);if(!after||before===after)return '';let unit=['chain','leech'].includes(id)?'targets / cycle':['rail','sails'].includes(id)?'beams / cycle':id==='mortar'?'strikes / salvo':'shots / volley';return ' · '+(before?before+' → ':'')+after+' '+unit}
function upgradeComparison(d){let l=s.items[d.id]||0,n=l+1,fmt=v=>Number(v.toFixed(1)).toString();if(d.kind==='repair')return 'Hull '+Math.ceil(s.p.hp)+' → '+Math.ceil(Math.min(maxHP(),s.p.hp+35));if(d.kind==='weapon'){let unit=newWeaponIds.includes(d.id)?({corona:'damage / tick',plasmaRain:'damage / tick',ionGuard:'damage / contact',spire:'damage / strike',rupture:'damage / strike',flak:'payload damage',voidSeed:'blast damage',fence:'damage / tick',stasisNet:'damage / tick'})[d.id]||'damage / hit':['toxic','gravity','harpoon','ember','nanite'].includes(d.id)?'damage / tick':d.id==='blade'?'damage / contact':['scatter','rapid'].includes(d.id)?'damage / projectile':'base damage';return (l?fmt(previewDamage(d.id,l))+' → ':'')+fmt(previewDamage(d.id,n))+' '+unit+volleyUpgradeHint(d.id,l,n)+' · before crits, protection and conditional synergies'}
 if(newSupportIds.includes(d.id))return (l?supportPreview(d.id,l)+' → ':'New: ')+supportPreview(d.id,n);let metric={area:[x=>100+12*x,'weapon area %'],velocity:[x=>100+12*x,'projectile speed %'],reach:[x=>100+15*x,'weapon reach %'],luck:[x=>100+20*x,'luck %'],thorns:[x=>12*x,'retaliation damage'],hull:[x=>s.pilot.hp+20*x,'maximum HP'],power:[x=>100+10*x,'weapon damage %'],scholar:[x=>100+10*x+(s.module==='collector'?15:0),'gem XP %'],shield:[x=>20*x*(s.spec?.shield==='capacity'?1.4:1),'maximum shield'],armour:[x=>2*x+s.pilot.armour,'flat damage reduction'],regen:[x=>.6*x+(s.pilot.regen||0)+(s.mutations.overflow?1:0),'HP / second'],clock:[x=>(1-.09*x)*100,'weapon cycle time %'],magnet:[x=>48+35*x,'XP pickup radius'],crit:[x=>5+8*x,'critical chance %'],speed:[x=>s.pilot.speed*(1+.09*x),'movement speed'],repulse:[x=>(100+22*x)*areaMult(),'repulsion radius'],intercept:[x=>Math.max(.35,2.8-.45*x)/velocityMult(),'intercept recovery seconds'],phase:[x=>(24-3*x)/velocityMult(),'safeguard recovery seconds']}[d.id];return metric?(l?fmt(metric[0](l))+' → ':'New: ')+fmt(metric[0](n))+' '+metric[1]:''}
