function shipPainter(ctx){let poly=(points,fill,stroke,width=1)=>{ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}};let circle=(x,y,r,color,fill=true)=>{ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx[fill?'fillStyle':'strokeStyle']=color;fill?ctx.fill():ctx.stroke()};return {ctx,poly,circle,hex:(r,fill,stroke,width=1)=>poly(Array.from({length:6},(_,i)=>[Math.cos(i*TAU/6)*r,Math.sin(i*TAU/6)*r]),fill,stroke,width),lineLocal:(x,y,bx,by,c,width)=>{ctx.strokeStyle=c;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(bx,by);ctx.stroke()}}}
