function toolShop(){return '<div class="shop-intro"><h3>More choices. Every run.</h3><p>Each permanent rank adds one starting use. Three ranks per tool. Purchases apply to your next run.</p></div><div class="tool-list">'+Object.entries(toolPrices).map(([id,prices])=>{let rank=hangar.tools[id],name={skips:'Skips',rerolls:'Rerolls',banishes:'Banishes'}[id],desc={skips:'Pass on an upgrade without taking it.',rerolls:'Replace the offered upgrade cards.',banishes:'Remove an item from this run’s upgrade pool.'}[id],cost=prices[rank],enough=hangar.credits>=cost;return '<article class="tool-row"><div><h3>'+name+'</h3><p>'+desc+'</p><div class="rank-pips" aria-label="'+rank+' of 3 purchased ranks">'+[0,1,2].map(n=>'<i class="'+(n<rank?'filled':'')+'"></i>').join('')+'</div></div><div class="tool-allowance"><small>STARTING USES</small><strong>'+ (3+rank)+(rank<3?' <span>→</span> '+(4+rank):' · MAX')+'</strong><small>'+rank+' / 3 ranks purchased</small></div><div class="tool-purchase"><b>'+(rank<3?cost+' credits':'Fully upgraded')+'</b><button data-hangar-action="tool" data-id="'+id+'" '+(rank>=3||!enough?'disabled':'')+'>'+(rank>=3?'Maximum rank':enough?'Buy permanent rank':'Need '+(cost-hangar.credits)+' more')+'</button></div></article>'}).join('')+'</div><details class="earning-note"><summary>How do I earn credits?</summary><p>1 per 25 kills · 1 per minute survived · 10 per boss · 8 per cleared breach, plus contract bonuses. Defeat keeps your earnings. Opening the Hangar during a paused run banks your current progress.</p></details>'}
