function pilotPicker(){if(!shipOwned(selectedPilot))selectedPilot='vanguard';let p=pilots.find(p=>p.id===(state==='preflight'?preflightShip:selectedPilot))||pilots[1],c=shipChallenges[p.id],owned=shipOwned(p.id),n=Math.min(c.goal,c.value(hangar)),fmt=x=>c.time?time(x):Math.floor(x).toLocaleString();$('pilotPicker').innerHTML='<div class="preflight-ship-layout"><div class="preflight-roster" role="group" aria-label="Choose your ship">'+pilots.map(q=>'<button class="preflight-ship '+lockedStateTag(q.id)+'" data-pilot="'+q.id+'" aria-pressed="'+(q.id===p.id)+'">'+shipIcon(q,'roster-icon')+'<b>'+q.name+'</b><small>'+(shipOwned(q.id)?'Owned':shipReady(q.id)?'Ready to buy':'Locked')+'</small>'+(!shipOwned(q.id)&&!shipReady(q.id)?'<i class="unlock-meter"><i style="width:'+Math.round(shipUnlockProgress(q.id)*100)+'%"></i></i>':'')+'</button>').join('')+'</div><article class="ship-detail preflight-detail"><div class="ship-detail-heading">'+shipIcon(p)+'<div><small>'+p.role.toUpperCase()+'</small><h3 style="color:'+p.color+'">'+p.name+'</h3><span class="status-badge">'+(owned?'READY TO FLY':'LICENCE REQUIRED')+'</span></div></div><div class="ship-specs"><span><b>'+p.hp+'</b> HP</span><span><b>'+p.speed+'</b> speed</span><span><b>'+p.armour+'</b> armour</span></div><p class="starter-line">Starting weapon: <b>'+defs.find(d=>d.id===p.starter).name+'</b></p><div class="ship-trait"><small>PASSIVE · '+shipTraits[p.id].name+'</small><p>'+shipTraits[p.id].desc+'</p></div><div class="ship-ability"><b>'+mobility[p.id].name+'</b><p>'+shipAbilityDescription(p.id)+'</p></div>'+(!owned?'<div class="unlock-box"><b>'+c.cost.toLocaleString()+' credits · licence price</b><p>'+c.desc+'<br>'+fmt(n)+' / '+fmt(c.goal)+'</p><button id="preflightBuy">View licence in Hangar →</button></div>':'')+'</article></div>'}
function openPreflight(){if(!['menu','end','pause'].includes(state))return;bayFx.scan=reducedMotion?0:.001;preflightReturn=state;parentScreen(state,false);state='preflight';preflightStep='ship';selectedPilot=preflightShip=treePilot();resetInput();show('preflight',true);renderPreflight();$('preflightNext').focus?.()}
function renderPreflight(){if(hangar?.sector)sectorTexture(hangar.sector);let shipStep=preflightStep==='ship',p=pilots.find(p=>p.id===preflightShip)||pilots[1];show('preflightShips',shipStep);show('preflightSectors',!shipStep);$('preflightTitle').textContent=shipStep?'Your ship':'Star map';$('preflightHint').textContent=shipStep?'Spend skill points to upgrade your ship, change class and build your loadout.':'Pick a planet. Beat 2 of its 3 reactor bosses to open the route to the next one.';$('preflightShipStep').setAttribute('aria-current',shipStep?'step':'false');$('preflightSectorStep').setAttribute('aria-current',shipStep?'false':'step');$('preflightBack').textContent=shipStep?(preflightReturn==='pause'?'Back to paused run':preflightReturn==='end'?'Back to results':'Back to menu'):'← Your ship';$('preflightNext').disabled=shipStep?!shipOwned(p.id):!shipOwned(selectedPilot)||!sectorOpen(hangar.sector);$('preflightNext').textContent=shipStep?'Star map →':'Launch →';if(shipStep){bayFx.build=bayBuild();$('pilotPicker').innerHTML=renderShipScreen();startShipBay();animateStatChanges()}else{$('preflightLoadout').textContent=pilotName(selectedPilot)+' → '+(sectors.find(x=>x.id===hangar.sector)||sectors[0]).name+' · '+(frames.find(x=>x.id===hangar.frame)||frames[0]).name+' · '+(modules.find(x=>x.id===hangar.module)||modules[0]).name;$('preflightSectorCards').innerHTML=renderStarMap();placeMapShip(true);startStarMap();$('preflightLoadout').innerHTML=starMapDetail()+missionStrip()}updateLaunchSummary()}
function selectPreflightShip(id){if(state!=='preflight'||preflightStep!=='ship'||!pilots.some(p=>p.id===id))return;preflightShip=id;if(shipOwned(id)){selectedPilot=id;try{profileStorage.setItem('ns_pilot',id)}catch(e){}}renderPreflight()}
function selectPreflightSector(id){if(state!=='preflight'||preflightStep!=='sector'||!sectors.some(x=>x.id===id)||!sectorOpen(id))return;if(id!==hangar.sector){mapFrom=hangar.sector;try{sound('dash')}catch(e){}}hangar.sector=id;saveHangar();renderPreflight()}
function advancePreflight(){if(state!=='preflight')return;if(preflightStep==='ship'&&!launchDone&&!reducedMotion&&typeof document!=='undefined'&&document.getElementById('shipBay')&&document.getElementById('shipBay').offsetParent){if(launchBusy)return;launchBusy=true;bayFx.launch=.001;try{sound('dash')}catch(e){}setTimeout(()=>warpTransition(()=>{launchBusy=false;launchDone=true;bayFx.launch=0;advancePreflight();launchDone=false}),620);return}if(preflightStep==='ship'){preflightShip=treePilot();selectedPilot=preflightShip;if(!sectorOpen(hangar.sector))hangar.sector='grid';preflightStep='sector';renderPreflight();$('preflightBody').scrollTop=0;return}if(!shipOwned(selectedPilot)||!sectorOpen(hangar.sector))return;show('preflight',false);state=preflightReturn;expeditionNext=true;start();openLaunchCards()}
function backPreflight(){if(state!=='preflight')return;if(preflightStep==='sector'){preflightStep='ship';selectedPilot=preflightShip=treePilot();renderPreflight();$('preflightBody').scrollTop=0;return}show('preflight',false);state=preflightReturn;parentScreen(state,true);if(state==='pause')renderPauseOverview();updateLaunchSummary()}
$('preflightNext').onclick=advancePreflight;$('pilotPicker').addEventListener('click',e=>{if(state==='preflight'&&preflightStep==='ship')shipScreenClick(e)});$('preflightBack').onclick=backPreflight;$('preflightSectorCards').onclick=e=>{let b=e.target.closest('[data-preflight-sector]');if(b)selectPreflightSector(b.dataset.preflightSector)};

function syncMenuLayer(){if(document.body){let open=document.querySelector('.overlay:not(.hidden)');document.body.classList.toggle('menu-open',!!open);document.body.classList.toggle('menu-atmosphere',!!document.querySelector('#menu:not(.hidden),#paused:not(.hidden),#preflight:not(.hidden)'))}}
function parentScreen(mode,on){let id={menu:'menu',preflight:'preflight',pause:'paused',end:'end'}[mode];if(id)show(id,on)}

const shipTraits={
wasp:{name:'Afterdash Overclock',desc:'20% faster weapon firing for 3 seconds after using a dash.'},
vanguard:{name:'Pristine Reactor',desc:'Deal 10% more weapon damage while above 75% hull.'},
bastion:{name:'Siege Stabilisers',desc:'Siege Cannon deals 20% more damage after holding position for half a second.'},
harrier:{name:'Point-Blank Assault',desc:'Deal 20% more weapon damage to enemies within 150 range.'},
glacier:{name:'Brittle Hulls',desc:'Deal 20% more weapon damage to frozen enemies. Retains 0.5 HP/sec repair.'},
tempest:{name:'Arc Feedback',desc:'Arc Discs gain 15% damage per enemy already pierced, up to 45% extra.'},
scavenger:{name:'Salvage Dividend',desc:'Earn 20% extra run credits, rounded down. Contract bonuses are unchanged.'},
spectre:{name:'Phase Ambush',desc:'Deal 35% more weapon damage for 3 seconds after Phase Shift ends.'},
architect:{name:'Field Engineer',desc:'Tesla Buoys, Plasma Mines, Gravity Well and Orbital Mortar deal 25% more damage.'},
helios:{name:'Solar Reclamation',desc:'Gas ignitions restore 3 HP, at most once per second.'},
echo:{name:'Resonant Pressure',desc:'Your Sonic Pulses slow enemies for 1 second. Deal 15% more damage to slowed targets.'},
sovereign:{name:'Imperial Arsenal',desc:'Each evolved weapon grants 4% extra weapon damage, up to 24%. Your Singularity Jump rift does not receive this bonus.'}
};
$('end').addEventListener('click',e=>{let button=e.target.closest('[data-view-unlocks]');if(button){hangarTab='ships';hangarInspect=button.dataset.viewUnlocks;openHangar()}});
function arcFeedback(b){return s.pilot.id==='tempest'&&b.weapon==='arc'?1+.15*Math.min(3,Math.max(0,[...b.seen].filter(t=>!t.debris).length-1)):1}
function traitDamage(e,source,owner){let id=s.pilot.id,weapon=damageOwner(source,owner);if(weapon==='other')return 1;if(id==='vanguard'&&s.p.hp>maxHP()*.75)return 1.1;if(id==='bastion'&&weapon==='cannon'&&(s.traitStill||0)>=.5)return 1.2;if(id==='harrier'&&dist(e,s.p)<150)return 1.2;if(id==='glacier'&&e.freeze>0)return 1.2;if(id==='spectre'&&s.ambushTime>0)return 1.35;if(id==='architect'&&['buoy','mines','gravity','mortar'].includes(weapon))return 1.25;if(id==='echo'&&e.slow>0)return 1.15;if(id==='sovereign')return 1+.04*Math.min(6,Object.keys(s.evolved).length);return 1}
function runCreditBreakdown(){let base=Math.floor(s.kills/25)+s.bossKills*10+s.metrics.breaches*8+Math.floor(s.t/60)+(s.salvageCredits||0)+endlessCycleCredits();return {base,bonus:s.pilot.id==='scavenger'?Math.floor(base*.2):0}}
function liveChallengeProgress(){if(s?.dev?.test)return hangar;let h={...hangar,progress:{...hangar.progress},evolutions:[...new Set([...hangar.evolutions,...Object.keys(s.evolved)])]},old=s.hangarCheckpoint||{},delta=(key,value)=>Math.max(0,value-(old[key]||0));h.kills+=delta('kills',s.kills);h.bosses+=delta('bosses',s.bossKills);h.breaches+=delta('breaches',s.metrics.breaches);h.starterBosses+=delta('starterBosses',s.starterBosses||0);if(s.completed&&!old.won){h.wins++;if(s.pilot.id==='glacier')h.glacierWins++}for(let [key,value] of Object.entries({...contractRunCounters(),gems:s.metrics.gems,freezes:s.metrics.freezes||0,ignitions:s.metrics.ignitions,cannonKills:s.weaponStats?.cannon?.kills||0,buoyKills:s.weaponStats?.buoy?.kills||0,cleanBoss:s.metrics.cleanBoss||0}))h.progress[key]+=Math.max(0,value-(old.progress?.[key]||0));h.progress.maxTime=Math.max(h.progress.maxTime,s.t);applyContractBests(h,s,!!s.completed);return h}
function initShipIdentity(){startRunMissions();try{if(s&&s.pilot)preloadBakedShip(s.pilot)}catch(e){}s.flightVisual={heading:0,thrust:0,bank:0};kbSm.x=kbSm.y=0;s.abilityBuffer=null;s.abilityLanding=null;s.abilityReadyNotice=0;s.mobilityDurations=null;s.riftWake=null;s.ambushTime=0;s.overclockTime=0;s.solarRepairCD=0;s.traitStill=0;s.traitLastPos={...s.p};s.shipTrails=[];s.trailClock=0;s.challengeClock=0;s.challengeStart={};s.challengeNotified=[];s.contractNotified=contracts.filter(c=>hasContract(c.id)||c.value(hangar)>=c.goal).map(c=>c.id);s.contractCompletions=[];s.unlockNotices=[];for(let [id,c] of Object.entries(shipChallenges)){s.challengeStart[id]=Math.min(c.goal,c.value(hangar));if(c.value(hangar)>=c.goal||shipOwned(id))s.challengeNotified.push(id)}}
function updateIdentity(dt){let previousPhase=s.phaseTime||0;s.ambushTime=Math.max(0,(s.ambushTime||0)-dt);s.overclockTime=Math.max(0,(s.overclockTime||0)-dt);s.solarRepairCD=Math.max(0,(s.solarRepairCD||0)-dt);if(s.pilot.id==='spectre'&&previousPhase>0&&previousPhase<=dt)s.ambushTime=3;let moved=dist(s.p,s.traitLastPos||s.p);s.traitStill=moved<.3?(s.traitStill||0)+dt:0;s.traitLastPos={x:s.p.x,y:s.p.y};s.trailClock-=dt;if(graphicsParticles()>0&&s.trailClock<=0&&(moved>.5||s.dashTime>0||s.boostTime>0||s.phaseTime>0)){s.trailClock=.055;let life=s.pilot.id==='spectre'?.55:.35;s.shipTrails.push({x:s.p.x,y:s.p.y,a:s.hullFace||0,life,max:life});s.shipTrails=s.shipTrails.slice(-Math.max(1,Math.round(42*graphicsParticles())))}for(let p of s.shipTrails)p.life-=dt;s.shipTrails=s.shipTrails.filter(p=>p.life>0);if(s.abilityVisual)s.abilityVisual.life-=dt;
 s.challengeClock-=dt;if(s.challengeClock<=0){s.challengeClock=.5;let h=liveChallengeProgress();for(let [id,c] of Object.entries(shipChallenges))if(false&&!s.challengeNotified.includes(id)&&c.value(h)>=c.goal){s.challengeNotified.push(id);if(!s.unlockNotices.length)sound('reward');s.unlockNotices.push({id,life:5});s.unlockNotices=s.unlockNotices.slice(-pilots.length)}if(!s.dev?.test)for(let c of contracts)if(!s.contractNotified.includes(c.id)&&c.value(h)>=c.goal){s.contractNotified.push(c.id);if(!s.unlockNotices.length)sound('reward');s.unlockNotices.push({id:'contract:'+c.id,contract:c.id,life:4});s.unlockNotices=s.unlockNotices.slice(-12)}}if(s.unlockNotices.length){s.unlockNotices[0].life-=dt;if(s.unlockNotices[0].life<=0)s.unlockNotices.shift()}}
function identityHUD(){let pending=Math.max(0,runCredits()-(s.hangarCheckpoint?.earned||0));$('creditHUD').textContent=(hangar.credits+pending).toLocaleString()+' CR · +'+runCredits()+' run';let notice=s.unlockNotices?.[0];show('unlockNotice',state==='play'&&!!notice);if(notice&&$('unlockNotice').dataset.ship!==notice.id){$('unlockNotice').dataset.ship=notice.id;if(notice.contract){let c=contracts.find(c=>c.id===notice.contract);$('unlockNotice').innerHTML='<small>ACHIEVEMENT COMPLETE</small><b>'+c.name+'</b><span>+'+c.reward+' credits when progress is banked</span>'}else{let p=pilots.find(x=>x.id===notice.id);s.unlockNotices.shift();return;$('unlockNotice').innerHTML='<small>SHIP CHALLENGE COMPLETE</small><b>'+p.name+'</b><span>Licence ready in Hangar · '+shipChallenges[p.id].cost+' credits</span>'}}let active=s.ambushTime>0?'AMBUSH '+s.ambushTime.toFixed(1)+'s':s.overclockTime>0?'OVERCLOCK '+s.overclockTime.toFixed(1)+'s':s.pilot.id==='bastion'&&s.traitStill>=.5?'STABILISERS READY':s.pilot.id==='sovereign'&&Object.keys(s.evolved).length?'ARSENAL +'+Math.min(24,4*Object.keys(s.evolved).length)+'%':'';if(active)$('abilityHUD').innerHTML+='<span class="trait-active">'+active+'</span>'}
function unlockResults(){let h=liveChallengeProgress(),rows=pilots.filter(p=>!shipOwned(p.id)).map(p=>{let c=shipChallenges[p.id],value=Math.min(c.goal,c.value(h)),start=s.challengeStart?.[p.id]||0;return {p,c,value,start,ready:value>=c.goal}}).sort((a,b)=>Number(b.ready)-Number(a.ready)||(b.value-b.start)/b.c.goal-(a.value-a.start)/a.c.goal||b.value/b.c.goal-a.value/a.c.goal).slice(0,2);return rows.length?'<section class="unlock-results"><h3>Your next ships</h3><div class="unlock-result-grid">'+rows.map(({p,c,value,start,ready})=>{let fmt=n=>c.time?time(n):Math.floor(n).toLocaleString();return '<article><b style="color:'+p.color+'">'+p.name+'</b><p>'+c.desc+'</p><div class="track"><div class="fill" style="width:'+value/c.goal*100+'%"></div></div><small>'+fmt(value)+' / '+fmt(c.goal)+(value>start?' · +'+fmt(value-start)+' this run':'')+'</small><strong>'+ (ready?'Challenge complete · '+c.cost+' credits':'Licence price · '+c.cost+' credits')+'</strong></article>'}).join('')+'</div><p class="fine">Challenge completion unlocks the licence for purchase. Owned ships stay available.</p><button data-view-unlocks="'+rows[0].p.id+'">View ship unlocks →</button></section>':''}
function drawIdentityTrails(){if(!graphicsParticles())return;let id=s.pilot.id,c=s.pilot.color;ctx.save();for(let p of s.shipTrails||[]){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);ctx.globalAlpha=Math.max(0,p.life/p.max)*.35;ctx.strokeStyle=c;ctx.lineWidth=1.3;if(id==='sovereign'){for(let n=0;n<2;n++)poly([[-8-n*12,0],[-17-n*12,-10],[-26-n*12,0],[-17-n*12,10]],null,n?'#ffe0aa':c,1)}else if(id==='echo'){ctx.beginPath();ctx.arc(-8,0,12+(1-p.life/p.max)*12,Math.PI*.55,Math.PI*1.45);ctx.stroke()}else if(id==='tempest'){poly([[-10,-7],[-22,-3],[-17,0],[-31,6]],null,c,1)}else if(id==='spectre'){poly([[16,0],[-16,-10],[-10,0],[-16,10]],null,c,1)}else if(id==='glacier'){poly([[-12,-6],[-18,0],[-12,6],[-6,0]],null,c,1)}else if(id==='architect'){ctx.strokeRect(-16,-8,5,5);ctx.strokeRect(-16,3,5,5)}else if(id==='scavenger'){circle(-17,-7,2,c);circle(-24,5,1,c)}else{let spread=id==='bastion'?14:id==='harrier'?18:8;for(let side of [-1,1])poly([[-12,side*spread-2],[-30,side*spread],[-12,side*spread+2]],id==='helios'?'#ffb36d':c)}ctx.restore()}ctx.restore()}
function drawAbilityBurst(v,c,age){if(!v)return;let id=s.pilot.id,prof=fleetHullProfiles[id],dx=s.p.x-v.x,dy=s.p.y-v.y,moved=Math.hypot(dx,dy);ctx.save();ctx.globalCompositeOperation='lighter';
 // Launch flash at the start point.
 let f=Math.max(0,1-age/.45);if(f>0){ctx.globalAlpha=f*.55;let g=ctx.createRadialGradient(v.x,v.y,0,v.x,v.y,30+age*90);g.addColorStop(0,'#ffffff');g.addColorStop(.25,c);g.addColorStop(1,c+'00');circle(v.x,v.y,30+age*90,g)}
 // Afterimages: fading hull silhouettes along the path travelled.
 if(prof&&moved>14){let n=Math.min(5,Math.floor(moved/26)+1),ang=Math.atan2(dy,dx)+Math.PI/2;for(let k=0;k<n;k++){let q=(k+.5)/n,x=v.x+dx*q,y=v.y+dy*q;ctx.save();ctx.translate(x,y);ctx.rotate(ang);ctx.globalAlpha=Math.max(0,(1-age)*(.12+.22*q));poly(prof.map(([px,py])=>[px*.95,py*.95]),c,null,0);ctx.restore()}
  ctx.globalAlpha=(1-age)*.5;ctx.strokeStyle=c;ctx.lineWidth=6*(1-age)+1;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(v.x,v.y);ctx.lineTo(s.p.x-dx/moved*12,s.p.y-dy/moved*12);ctx.stroke()}
 // Abilities that don't move the ship get an expanding shockwave instead of a trail.
 if(moved<=14){ctx.globalAlpha=Math.max(0,(1-age)*.75);ctx.strokeStyle=c;ctx.lineWidth=5*(1-age)+1;ctx.beginPath();ctx.arc(s.p.x,s.p.y,22+age*85,0,TAU);ctx.stroke();ctx.globalAlpha=Math.max(0,(1-age)*.18);circle(s.p.x,s.p.y,22+age*85,c)}
 // A soft glow that stays on the ship for the active part of the ability.
 ctx.globalAlpha=Math.max(0,.4*(1-age));let g2=ctx.createRadialGradient(s.p.x,s.p.y,0,s.p.x,s.p.y,44);g2.addColorStop(0,c+'aa');g2.addColorStop(1,c+'00');circle(s.p.x,s.p.y,44,g2);ctx.restore()}
function drawIdentityAbility(){let v=s.abilityVisual;if(!v||v.life<=0)return;let age=reducedMotion?0:1-v.life/.75,id=s.pilot.id,c=s.pilot.color;drawAbilityBurst(v,c,age);ctx.save();ctx.translate(v.x,v.y);ctx.rotate(v.a);ctx.globalAlpha=Math.min(.9,v.life*2.2);ctx.strokeStyle=c;ctx.lineWidth=2.6;if(id==='sovereign'){for(let i=0;i<3;i++){ctx.save();ctx.rotate(i*Math.PI/3);poly([[-28-age*20,0],[0,-12-age*8],[28+age*20,0],[0,12+age*8]],(i%2?'#ffe3ad':c)+'30',i%2?'#ffe3ad':c,1.5);ctx.restore()}}else if(['echo','vanguard','scavenger'].includes(id)){let n=id==='echo'?3:id==='vanguard'?2:1;for(let i=0;i<n;i++){ctx.setLineDash(id==='scavenger'?[4,7]:[]);circle(0,0,20+age*(id==='scavenger'?120:65)+i*12,c,false)}}else if(id==='glacier'){for(let i=0;i<6;i++){ctx.save();ctx.rotate(i*TAU/6);lineLocal(10,0,35+age*30,0,c,2);poly([[25,-6],[31,0],[25,6]],c+'30',c,1);ctx.restore()}}else if(id==='architect'){for(let i=0;i<4;i++){ctx.save();ctx.rotate(i*TAU/4);poly([[15,-8],[32,-8],[32,8],[15,8]],c+'30',c,2);ctx.restore()}}else if(id==='tempest'){for(let side of [-1,1])poly([[-40,side*24],[-12,side*9],[0,side*17],[35,0]],c+'30',c,2)}else if(id==='spectre'){for(let i=1;i<=3;i++)poly([[-i*18+14,0],[-i*18-12,-12],[-i*18-6,0],[-i*18-12,12]],c+'30',c,1)}else if(id==='bastion'){poly([[10,-30],[40+age*30,-20],[55+age*30,0],[40+age*30,20],[10,30]],c+'30',c,2)}else{for(let i=0;i<(id==='wasp'?3:2);i++)poly([[-i*18+10,-15],[-i*18+25,0],[-i*18+10,15]],c+'30',c,2)}ctx.restore()}
